import {abilities,skills} from './lib/rules.js';
import {previewLiveCheck} from './lib/srd-live-check-preview.mjs';
import {spellDiceFields,spellDiceField,spellDiceText} from './spell-dice-fields.js';
import {copy,htmlCopy} from './locale.js';
const options=names=>names.map(n=>`<option>${n}</option>`).join('');
export function liveCheckHTML(play){return `<details class="play-live-check"><summary>${htmlCopy('Quick check preview')}</summary><p>${htmlCopy('Dodge automatically grants Advantage on Dexterity saves while active. Enter two dice unless Disadvantage cancels it.')} ${htmlCopy('Read-only. Uses sheet modifiers and recorded Exhaustion. Confirm other effects, roll replacements, cover, visibility and GM rulings separately. Enter a signed additional bonus or penalty if applicable. No resource or save changes.')}</p>${['skill','save'].map(kind=>`<form data-live-check="${kind}" class="enc-inline"><h4>${htmlCopy(kind==='skill'?'Skill check':'Saving Throw')}</h4><label>${htmlCopy('Check') }<select name="name">${options(kind==='skill'?Object.keys(skills):abilities)}</select></label><label>${htmlCopy('First d20')}<input type="number" name="first" min="1" max="20" required></label><label>${htmlCopy('Second d20 if needed')}<input type="number" name="second" min="1" max="20"></label><label><input type="checkbox" name="advantage">${htmlCopy('Advantage')}</label><label><input type="checkbox" name="disadvantage">${htmlCopy('Disadvantage')}</label><label>${htmlCopy('Additional modifier')}<input type="number" name="bonus" min="-100" max="100" value="0" required></label>${kind==='save'?spellDiceFields(play,'save'):''}<label>${htmlCopy('DC (optional)')}<input type="number" name="dc" min="1" max="999"></label><label><input type="checkbox" name="confirmed" required>${htmlCopy('I confirmed other applicable effects and the situation with the table.')}</label><button type="submit">${htmlCopy('Preview result')}</button><output data-live-check-result role="status" aria-live="polite"></output></form>`).join('')}</details>`;}
export function resolveLiveCheckForm(form,profile,play){
 const fields=new FormData(form); const second=fields.get('second');
 const result=previewLiveCheck(profile,play,{kind:form.dataset.liveCheck,name:fields.get('name'),rolls:[Number(fields.get('first')),...(second===''?[]:[Number(second)])],advantage:fields.has('advantage'),disadvantage:fields.has('disadvantage'),otherBonus:Number(fields.get('bonus')),dc:fields.get('dc')===''?null:Number(fields.get('dc')),confirmed:fields.has('confirmed'),...spellDiceField(fields)});
 if(result.status==='automatic-failure')return copy('Automatic failure from recorded condition.');
 const status=result.status==='unresolved'?copy('GM sets the DC.'):copy(result.status==='success'?'Success':'Failure');
 return `${result.name}: d20 ${result.natural} (${copy({normal:'Normal',advantage:'Advantage',disadvantage:'Disadvantage'}[result.mode])}); ${copy('Sheet modifier')} ${result.characterBonus}; ${copy('Exhaustion penalty')} −${result.exhaustionPenalty}; ${copy('Additional modifier')} ${fields.get('bonus')}; ${result.spellDice.length?spellDiceText(result.spellDice)+'; ':''}${copy('Total')} ${result.total}. ${status}`;
}

// Render only the oldest check. No arbitrary DC or ability input is exposed.
export function concentrationRollHTML(play){
 const head=play.concentrationChecks[0];
 if(!head||!play.focus||play.dead||play.hp<=0||play.shape?.active)return '';
 return `<form data-play-form="concentration-roll" class="enc-inline" data-focus="${htmlCopy('{effect}',{effect:play.focus})}" data-damage="${head.damage}" data-dc="${head.dc}" data-pending-count="${play.concentrationChecks.length}"><h4>${htmlCopy('Resolve pending Concentration save')}</h4><p>${htmlCopy('Use the recorded DC. Confirm situational effects and enter physical dice; this records the result and may end Concentration.')}</p><label>${htmlCopy('First d20')}<input type="number" name="first" min="1" max="20" required></label><label>${htmlCopy('Second d20 if needed')}<input type="number" name="second" min="1" max="20"></label><label><input type="checkbox" name="advantage">${htmlCopy('Advantage')}</label><label><input type="checkbox" name="disadvantage">${htmlCopy('Disadvantage')}</label><label>${htmlCopy('Additional modifier')}<input type="number" name="bonus" min="-100" max="100" value="0" required></label>${spellDiceFields(play,'save')}<label><input type="checkbox" name="confirmed" required>${htmlCopy('I confirmed other applicable effects and the situation with the table.')}</label><button type="submit">${htmlCopy('Record calculated save')}</button></form>`;
}
export function concentrationRollCommand(form,fields){
 const second=fields.get('second');
 return {type:'concentration-roll',focus:form.dataset.focus,damage:Number(form.dataset.damage),dc:Number(form.dataset.dc),pendingCount:Number(form.dataset.pendingCount),rolls:[Number(fields.get('first')),...(second===''?[]:[Number(second)])],advantage:fields.has('advantage'),disadvantage:fields.has('disadvantage'),otherBonus:fields.get('bonus')===''||fields.get('bonus')===null?NaN:Number(fields.get('bonus')),confirmed:fields.has('confirmed'),...spellDiceField(fields)};
}
